import { Component, computed, effect, inject, resource, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { DatePipe } from '@angular/common';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { firstValueFrom, map } from 'rxjs';
import { Solicitud, SolicitudTramite } from '../../../shared/models/solicitud.model';
import { semaforoColorClass } from '../../../shared/models/solicitud-status.util';
import { ETAPA_TRAMITE_LABELS, NIVEL_GOBIERNO_LABELS } from '../../../shared/models/tramite-labels';
import { SolicitudService } from '../../../shared/services/solicitud.service';
import { TramiteService } from '../../../shared/services/tramite.service';
import { ObservacionesService } from '../../../shared/services/observaciones.service';
import { AuthService } from '../../../services/auth.service';
import { NavigationHistoryService } from '../../../services/navigation-history.service';
import { HistorialTimelineComponent } from '../../../shared/components/historial-timeline/historial-timeline.component';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { CoordenadasPickerComponent } from '../../../shared/components/coordenadas-picker/coordenadas-picker.component';
import { ResolucionService } from '../../../shared/services/resolucion.service';
import { MachotePanelComponent } from '../../../shared/components/machote-panel/machote-panel.component';
import { ChatInversorComponent } from '../seguimiento-municipal/chat-inversor/chat-inversor.component';
import { BitacoraNotasComponent } from '../seguimiento-municipal/bitacora-notas/bitacora-notas.component';

@Component({
  selector: 'app-ejecutivos-detalle-solicitud',
  imports: [RouterLink, HistorialTimelineComponent, PdfViewerComponent, CoordenadasPickerComponent, DatePipe, ChatInversorComponent, BitacoraNotasComponent, MachotePanelComponent],
  templateUrl: './detalle-solicitud.component.html',
  styleUrl: './detalle-solicitud.component.scss',
})
export class DetalleSolicitudComponent {
  readonly semaforoColorClass = semaforoColorClass;

  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private solicitudService = inject(SolicitudService);
  private tramiteService = inject(TramiteService);
  private obsService = inject(ObservacionesService);
  private auth = inject(AuthService);
  private resolucionService = inject(ResolucionService);
  private navHistory = inject(NavigationHistoryService);

  readonly folio = this.route.paramMap
    ? toSignal(
        this.route.paramMap.pipe(map((params) => params.get('id') ?? '—')),
        { initialValue: this.route.snapshot?.paramMap?.get('id') ?? '—' },
      )
    : signal(this.route.snapshot?.paramMap?.get('id') ?? '—');

  readonly origen = signal<'ejecutivo' | 'inversor'>(
    (this.route.snapshot.data['origen'] as 'ejecutivo' | 'inversor') ?? 'ejecutivo',
  );

  readonly solicitudResource = resource({
    params: () => ({ folio: this.folio() }),
    loader: ({ params }) => firstValueFrom(this.solicitudService.getByFolio(params.folio)),
  });

  readonly solicitud = computed<Solicitud | null>(() => {
    return (this.solicitudResource.status() as string) === 'resolved' ? (this.solicitudResource.value() ?? null) : null;
  });
  readonly isLoading = computed(() => this.solicitudResource.isLoading());
  readonly hasError = computed(() => {
    return this.solicitudResource.hasValue() && !this.solicitudResource.value() || !!this.solicitudResource.error();
  });

  readonly correcciones = computed(() =>
    this.obsService
      .observacionesDe(this.folio())
      .filter((o) => o.status === 'pendiente')
      .map((o) => ({ id: o.id, descripcion: o.texto, fechaLimite: '—' })),
  );

  readonly esIncompleta = computed(() => this.solicitud()?.status === 'Incompleta');

  readonly mostrarCorrecciones = computed(
    () => this.esIncompleta() && this.correcciones().length > 0,
  );

  readonly mostrarTramites = computed(() => {
    const sol = this.solicitud();
    return sol && ['Autorizada', 'En Seguimiento', 'No Aprobada'].includes(sol.status);
  });

  /** Trámites asignados: sólo aplica al flujo de inversión, nunca a un trámite. */
  readonly tramitesResource = resource({
    params: () => {
      const sol = this.solicitud();
      if (!sol || sol.tipo === 'tramite') return undefined;
      return { folio: this.folio() };
    },
    loader: ({ params }) => {
      if (!params) return Promise.resolve([] as SolicitudTramite[]);
      return firstValueFrom(this.tramiteService.getTramitesAsignados(params.folio));
    },
  });

  readonly tramites = computed<SolicitudTramite[]>(() =>
    this.tramitesResource.hasValue() ? (this.tramitesResource.value() ?? []) : [],
  );

  readonly tramiteBanner = computed<{
    icono: string;
    titulo: string;
    mensaje: string;
    variante: string;
  } | null>(() => {
    const sol = this.solicitud();
    if (!sol || sol.tipo !== 'tramite') return null;
    switch (sol.status) {
      case 'En Análisis':
        return {
          icono: 'bi-search',
          titulo: 'Tu trámite está en análisis',
          mensaje: 'El área correspondiente está revisando la documentación de tu trámite.',
          variante: 'info',
        };
      case 'En Firma':
        return {
          icono: 'bi-pen',
          titulo: 'Tu trámite está en firma',
          mensaje: 'Tu trámite fue aprobado y está en proceso de firma por la autoridad.',
          variante: 'warning',
        };
      case 'Terminada':
        return {
          icono: 'bi-patch-check-fill',
          titulo: 'Trámite terminado',
          mensaje: 'Tu trámite ha concluido correctamente. Puedes consultar el documento firmado.',
          variante: 'success',
        };
      case 'No Autorizada':
        return {
          icono: 'bi-x-circle-fill',
          titulo: 'Trámite no autorizado',
          mensaje: 'Tu trámite no fue autorizado. Revisa los motivos en el seguimiento.',
          variante: 'danger',
        };
      default:
        return {
          icono: 'bi-hourglass-split',
          titulo: 'Tu trámite está en proceso',
          mensaje: 'Recibimos tu trámite y está en revisión por la autoridad.',
          variante: 'success',
        };
    }
  });
  
  readonly representanteLegalNombre = computed<string | null>(() => {
    const sol = this.solicitud();
    if (!sol) return null;
    const partes = [
      sol.nombreRepresentante,
      sol.primerApellidoRepresentante,
      sol.segundoApellidoRepresentante,
    ].filter((parte): parte is string => !!parte);
    return partes.length > 0 ? partes.join(' ') : null;
  });

  get regresarRoute(): string {
    return this.navHistory.getBackRoute(this.origen(), 'bandeja/recibidas', this.getQueryParams()['from']);
  }

  goBack(): void {
    this.router.navigateByUrl(this.regresarRoute);
  }

  constructor() {
    effect(() => {
      const f = this.folio();
      if (this.origen() === 'inversor' && f && f !== '—') {
        this.obsService.cargar(f);
      }
    });
  }

  estadoBadgeClass(estado: string): string {
    switch (estado) {
      case 'pendiente': return 'bg-warning text-dark';
      case 'documento_subido': return 'bg-info text-white';
      case 'completado': return 'bg-success';
      case 'rechazado': return 'bg-danger';
      default: return 'bg-secondary';
    }
  }

  etapaTramiteLabel(etapa: string | null): string {
    if (!etapa) return '';
    return ETAPA_TRAMITE_LABELS[etapa] ?? etapa;
  }

  nivelGobiernoTramiteLabel(nivel: string): string {
    return NIVEL_GOBIERNO_LABELS[nivel] ?? nivel;
  }

  readonly canAccessResolucion = computed(() => {
    const user = this.auth.currentUser();
    const sol = this.solicitud();
    if (!user || !sol || sol.tipo === 'tramite') return false;
    const isInternal = user.role === 'ejecutivo' || user.role === 'admin';
    return isInternal && sol.status === 'En Dictaminación';
  });

  readonly selectedDocId = signal<number | null>(null);
  readonly mostrarVisor = signal(false);
  readonly mostrarChat = signal(false);
  readonly mostrarBitacora = signal(false);

  seleccionarDocumento(id: number): void {
    this.selectedDocId.set(id);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
  }

  toggleChat(): void {
    this.mostrarChat.update(v => !v);
  }

  toggleBitacora(): void {
    this.mostrarBitacora.update(v => !v);
  }

  readonly canDesignarComite = computed(() => {
    const user = this.auth.currentUser();
    const sol = this.solicitud();
    if (!user || !sol || sol.tipo === 'tramite') return false;
    const isInternal = user.role === 'ejecutivo' || user.role === 'admin';
    return isInternal && ['Enviada', 'Incompleta', 'Subsanada', 'No Presentada'].includes(sol.status);
  });

  alMachoteStatusCambiado(): void {
    this.solicitudResource.reload();
  }

  getQueryParams(): Record<string, string> {
    const fromParam = this.route.snapshot.queryParamMap.get('from');
    return fromParam ? { from: fromParam } : {};
  }

  consultarResolucion(): void {
    const f = this.folio();
    if (!f || f === '—') return;
    this.resolucionService.getResoluciones(f).subscribe({
      next: (resoluciones) => {
        const firmada = resoluciones.find((r) => r.estado === 'Firmada' && r.tieneDocumento) ?? resoluciones[0];
        if (firmada && firmada.tieneDocumento) {
          this.resolucionService.descargarResolucion(f, firmada.id).subscribe({
            next: (blob) => {
              const url = URL.createObjectURL(blob);
              window.open(url, '_blank');
              setTimeout(() => URL.revokeObjectURL(url), 10000);
            },
          });
        }
      },
    });
  }
}
