import {
  Component,
  computed,
  DestroyRef,
  inject,
  input,
  output,
  resource,
  signal,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { DatePipe } from '@angular/common';
import { firstValueFrom } from 'rxjs';
import { Machote, SentidoMachote } from '../../models/machote.model';
import { statusToClass } from '../../models/solicitud-status.util';
import { MachoteService } from '../../services/machote.service';
import { SolicitudService } from '../../services/solicitud.service';
import { DocumentoService } from '../../../services/documento.service';
import { AuthService } from '../../../services/auth.service';
import { ToastService } from '../../services/toast.service';
import { extractErrorMessage } from '../../utils/error-utils';
import { descargarBlob } from '../../utils/download.util';
import { ToastContainerComponent } from '../toast-container/toast-container.component';
import {
  DocumentoAFirmar,
  FirmaEfirmaModalComponent,
  ResultadoFirma,
} from '../firma-efirma-modal/firma-efirma-modal.component';

const STATUS_ENVIABLES = ['Enviada', 'Incompleta', 'Subsanada'];
const STATUS_CON_MACHOTES = ['En Análisis', 'En Firma', 'Terminada', 'No Autorizada'];

function prioridadMachote(machote: Machote): number {
  if (machote.sentido === 'Autorizada') {
    return 2;
  }
  if (machote.documentoFirmadoId != null) {
    return 1;
  }
  return 0;
}

function machoteMasVigente(actual: Machote, candidato: Machote): Machote {
  const diferencia = prioridadMachote(candidato) - prioridadMachote(actual);
  if (diferencia !== 0) {
    return diferencia > 0 ? candidato : actual;
  }
  return candidato.version >= actual.version ? candidato : actual;
}

import { OficioTramiteEditorComponent } from '../oficio-tramite-editor/oficio-tramite-editor.component';

@Component({
  selector: 'app-machote-panel',
  templateUrl: './machote-panel.component.html',
  styleUrl: './machote-panel.component.scss',
  host: { class: 'd-block' },
  imports: [
    DatePipe,
    FirmaEfirmaModalComponent,
    ToastContainerComponent,
    OficioTramiteEditorComponent,
  ],
})
export class MachotePanelComponent {
  private readonly machoteService = inject(MachoteService);
  private readonly solicitudService = inject(SolicitudService);
  private readonly documentoService = inject(DocumentoService);
  private readonly authService = inject(AuthService);
  private readonly toastService = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);

  readonly folio = input.required<string>();
  readonly status = input.required<string>();
  readonly evaluadorId = input<number | null>(null);
  readonly solicitudId = input<number | null>(null);
  readonly statusCambiado = output<void>();

  readonly errorAccion = signal<string | null>(null);
  readonly enviando = signal(false);
  readonly generando = signal(false);
  readonly aprobando = signal(false);
  readonly preparandoFirma = signal(false);

  readonly sentido = signal<SentidoMachote>('Autorizada');
  readonly motivo = signal('');
  readonly machoteSeleccionadoId = signal<number | null>(null);

  readonly mostrarModalFirma = signal(false);
  readonly machoteParaFirmar = signal<Machote | null>(null);
  private unsignedPdfBytes: Uint8Array | null = null;

  readonly machotesResource = resource({
    params: () => ({ folio: this.folio(), status: this.status() }),
    loader: ({ params }): Promise<Machote[]> => {
      if (!STATUS_CON_MACHOTES.includes(params.status)) {
        return Promise.resolve<Machote[]>([]);
      }
      return firstValueFrom(this.machoteService.listar(params.folio));
    },
  });

  readonly machotes = computed<Machote[]>(() => this.machotesResource.value() ?? []);
  readonly cargando = computed(() => this.machotesResource.isLoading());
  readonly errorCarga = computed(() => {
    const err = this.machotesResource.error();
    return err ? extractErrorMessage(err) : null;
  });

  readonly esAdmin = computed(() => this.authService.currentUser()?.role === 'admin');
  readonly esInterno = computed(() => {
    const role = this.authService.currentUser()?.role;
    return role === 'ejecutivo' || role === 'admin';
  });

  readonly puedeEnviarAnalisis = computed(
    () => this.esInterno() && STATUS_ENVIABLES.includes(this.status()),
  );
  readonly enAnalisis = computed(() => this.status() === 'En Análisis');
  readonly enFirma = computed(() => this.status() === 'En Firma');
  readonly terminada = computed(() => this.status() === 'Terminada');
  readonly noAutorizada = computed(() => this.status() === 'No Autorizada');
  readonly statusClass = computed(() => statusToClass(this.status()));

  readonly puedeGenerar = computed(() => {
    const user = this.authService.currentUser();
    const esEvaluadorAsignado = user != null
      && this.evaluadorId() != null
      && user.id === this.evaluadorId();
    return this.esInterno() && this.enAnalisis() && (this.esAdmin() || esEvaluadorAsignado);
  });

  readonly machotesPendientes = computed(() => this.machotes().filter((m) => !m.aprobado));
  readonly machotePendiente = computed<Machote | null>(() => {
    const seleccionado = this.machotes().find((m) => m.id === this.machoteSeleccionadoId());
    if (seleccionado && !seleccionado.aprobado) {
      return seleccionado;
    }
    return this.machotesPendientes()[0] ?? null;
  });

  /** Versión vigente: la Autorizada aprobada (firmable), no la primera aprobada. */
  readonly machoteVigente = computed<Machote | null>(() => {
    const aprobados = this.machotes().filter((m) => m.aprobado);
    if (aprobados.length === 0) {
      return null;
    }
    return aprobados.reduce(machoteMasVigente);
  });

  /** Machote aprobado con sentido "No Autorizada" (estado terminal). */
  readonly machoteNoAutorizado = computed<Machote | null>(() => {
    const noAutorizados = this.machotes().filter(
      (m) => m.aprobado && m.sentido === 'No Autorizada',
    );
    if (noAutorizados.length === 0) {
      return null;
    }
    return noAutorizados.reduce((actual, candidato) =>
      candidato.version >= actual.version ? candidato : actual,
    );
  });

  readonly motivoNoAutorizada = computed(() => this.machoteNoAutorizado()?.motivo ?? null);

  readonly puedeAprobar = computed(
    () => this.esAdmin() && this.enAnalisis() && this.machotePendiente() !== null,
  );
  readonly puedeFirmar = computed(
    () => this.esAdmin() && this.enFirma() && this.machoteVigente()?.documentoId != null,
  );
  readonly motivoRequerido = computed(() => this.sentido() === 'No Autorizada');
  readonly motivoValido = computed(
    () => !this.motivoRequerido() || this.motivo().trim().length > 0,
  );

  readonly documentosAFirmar = computed<DocumentoAFirmar[]>(() => {
    const machote = this.machoteParaFirmar();
    if (!this.unsignedPdfBytes || !machote) {
      return [];
    }
    return [
      {
        nombre: this.nombreArchivo(machote, true),
        bytes: this.unsignedPdfBytes,
      },
    ];
  });

  enviarAEnAnalisis(): void {
    if (!this.puedeEnviarAnalisis() || this.enviando()) {
      return;
    }
    this.enviando.set(true);
    this.errorAccion.set(null);
    this.solicitudService
      .enviarAEnAnalisis(this.folio())
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.enviando.set(false);
          this.toastService.success('Trámite enviado a análisis.');
          this.statusCambiado.emit();
        },
        error: (err) => {
          this.enviando.set(false);
          this.errorAccion.set(extractErrorMessage(err));
        },
      });
  }

  generarMachote(): void {
    if (!this.puedeGenerar() || this.generando()) {
      return;
    }
    this.generando.set(true);
    this.errorAccion.set(null);
    this.machoteService
      .generar(this.folio())
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.generando.set(false);
          this.toastService.success('Machote generado.');
          this.machotesResource.reload();
        },
        error: (err) => {
          this.generando.set(false);
          this.errorAccion.set(extractErrorMessage(err));
        },
      });
  }

  onSentidoChange(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    this.sentido.set(value === 'No Autorizada' ? 'No Autorizada' : 'Autorizada');
  }

  onSeleccionarMachote(event: Event): void {
    const value = (event.target as HTMLSelectElement).value;
    const id = Number(value);
    this.machoteSeleccionadoId.set(Number.isNaN(id) ? null : id);
  }

  onMotivoInput(event: Event): void {
    this.motivo.set((event.target as HTMLTextAreaElement).value);
  }

  aprobarMachote(): void {
    const machote = this.machotePendiente();
    if (!this.puedeAprobar() || !machote || !this.motivoValido() || this.aprobando()) {
      return;
    }
    this.aprobando.set(true);
    this.errorAccion.set(null);
    this.machoteService
      .aprobar(this.folio(), machote.id, {
        sentido: this.sentido(),
        motivo: this.sentido() === 'No Autorizada' ? this.motivo().trim() : null,
      })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.aprobando.set(false);
          this.sentido.set('Autorizada');
          this.motivo.set('');
          this.toastService.success('Machote aprobado.');
          this.machotesResource.reload();
          this.statusCambiado.emit();
        },
        error: (err) => {
          this.aprobando.set(false);
          this.errorAccion.set(extractErrorMessage(err));
        },
      });
  }

  iniciarFirma(): void {
    const machote = this.machoteVigente();
    if (!machote?.documentoId || this.preparandoFirma()) {
      return;
    }
    this.preparandoFirma.set(true);
    this.errorAccion.set(null);
    this.documentoService
      .downloadDocumento(machote.documentoId)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (bytes) => {
          this.unsignedPdfBytes = bytes;
          this.machoteParaFirmar.set(machote);
          this.preparandoFirma.set(false);
          this.mostrarModalFirma.set(true);
        },
        error: (err) => {
          this.preparandoFirma.set(false);
          this.errorAccion.set(extractErrorMessage(err));
        },
      });
  }

  onFirmaCerrado(): void {
    this.mostrarModalFirma.set(false);
    this.machoteParaFirmar.set(null);
    this.unsignedPdfBytes = null;
  }

  onFirmaFirmado(resultados: ResultadoFirma[]): void {
    const machote = this.machoteParaFirmar();
    if (!machote || resultados.length === 0) {
      return;
    }
    const firmado = resultados[0];
    const firmaMetadata = JSON.stringify({
      folio: this.folio(),
      solicitudId: this.solicitudId() ?? null,
    });
    this.machoteService
      .firmar(this.folio(), machote.id, firmado.signedBytes, firmado.serial, firmaMetadata)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.mostrarModalFirma.set(false);
          this.machoteParaFirmar.set(null);
          this.unsignedPdfBytes = null;
          this.toastService.success('Machote firmado correctamente.');
          this.machotesResource.reload();
          this.statusCambiado.emit();
        },
        error: (err) => {
          const mensaje = extractErrorMessage(err);
          this.errorAccion.set(mensaje);
          this.toastService.error(mensaje);
        },
      });
  }

  descargarDocumento(id: number | null, nombre: string): void {
    if (!id) {
      return;
    }
    this.documentoService
      .downloadDocumento(id)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (bytes) => {
          const blob = new Blob([new Uint8Array(bytes)], { type: 'application/pdf' });
          descargarBlob(blob, nombre);
        },
        error: (err) => this.errorAccion.set(extractErrorMessage(err)),
      });
  }

  sentidoBadgeClass(machote: Machote): string {
    if (!machote.aprobado) {
      return 'bg-warning text-dark';
    }
    return machote.sentido === 'No Autorizada' ? 'bg-danger' : 'bg-success';
  }

  sentidoLabel(machote: Machote): string {
    if (!machote.aprobado) {
      return 'Pendiente';
    }
    return machote.sentido === 'No Autorizada' ? 'No Autorizada' : 'Aprobado';
  }

  nombreArchivo(machote: Machote, firmado: boolean): string {
    return `${firmado ? 'machote_firmado' : 'machote'}_${this.folio()}_v${machote.version}.pdf`;
  }

  alOficioGuardado(): void {
    this.machotesResource.reload();
  }
}
