import {
  Component,
  DestroyRef,
  computed,
  effect,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { QuillModule, ContentChange } from 'ngx-quill';
import type Quill from 'quill';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Machote } from '../../models/machote.model';
import { MachoteService } from '../../services/machote.service';
import { DocumentoService } from '../../../services/documento.service';
import { ToastService } from '../../services/toast.service';
import { extractErrorMessage } from '../../utils/error-utils';
import { descargarBlob } from '../../utils/download.util';
import { PdfViewerComponent } from '../pdf-viewer/pdf-viewer.component';

@Component({
  selector: 'app-oficio-tramite-editor',
  standalone: true,
  imports: [CommonModule, FormsModule, QuillModule, PdfViewerComponent],
  templateUrl: './oficio-tramite-editor.component.html',
  host: { class: 'd-block' },
})
export class OficioTramiteEditorComponent {
  private readonly machoteService = inject(MachoteService);
  private readonly documentoService = inject(DocumentoService);
  private readonly toastService = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);
  readonly folio = input.required<string>();
  readonly machote = input.required<Machote>();
  readonly puedeEditar = input(false);
  readonly oficioGuardado = output<Machote>();
  readonly verPdf = output<{ url?: string; documentoId?: number }>();
  readonly contenidoHtml = signal('');
  readonly numeroOficioInput = signal('');
  readonly asuntoInput = signal('Resolución del Trámite');
  readonly promoventeInput = signal('');
  readonly dependenciaInput = signal('');
  readonly seccionInput = signal('');
  readonly departamentoInput = signal('');
  readonly firmanteCargoInput = signal('');
  readonly firmanteNombreInput = signal('');
  readonly mostrarMetadatosInstitucionales = signal(false);
  readonly guardando = signal(false);
  readonly previsualizando = signal(false);
  readonly expandido = signal(false);
  readonly previewModalUrl = signal<string | null>(null);
  readonly previewModalDocId = signal<number | null>(null);
  private editorInstance: Quill | null = null;

  readonly quillModules = {
    table: true,
    toolbar: [
      [{ header: [1, 2, 3, false] }],
      ['bold', 'italic', 'underline'],
      [{ align: [] }],
      [{ list: 'ordered' }, { list: 'bullet' }],
      [{ indent: '-1' }, { indent: '+1' }],
      ['link', 'image'],
      ['clean'],
    ],
  };

  readonly tieneOficioDisponible = computed(() => {
    const m = this.machote();
    return !!(m.oficioDocumentoId || m.oficioHtml);
  });

  constructor() {
    effect(() => {
      const m = this.machote();
      this.contenidoHtml.set(m.oficioHtml || '');
      this.numeroOficioInput.set(m.numeroOficio || '');
      this.asuntoInput.set(m.asunto || 'Resolución del Trámite');

      const meta = m.oficioMetadata;
      if (meta) {
        this.dependenciaInput.set(meta['dependencia'] || '');
        this.seccionInput.set(meta['seccion'] || '');
        this.departamentoInput.set(meta['departamento'] || '');
        this.firmanteCargoInput.set(meta['firmante_cargo'] || '');
        this.firmanteNombreInput.set(meta['firmante_nombre'] || '');
      }
    });
  }

  onEditorCreated(editor: Quill): void {
    this.editorInstance = editor;
  }

  onContentChanged(event: ContentChange): void {
    this.contenidoHtml.set(event.html || '');
  }

  toggleExpandido(): void {
    this.expandido.update((v) => !v);
  }

  insertarTabla(filas: number, columnas: number): void {
    const tableModule = this.editorInstance?.getModule('table') as {
      insertTable?: (rows: number, cols: number) => void;
    } | null;
    if (tableModule?.insertTable) {
      tableModule.insertTable(filas, columnas);
    } else {
      this.toastService.error('El editor no está listo. Abre el editor antes de insertar una tabla.');
    }
  }

  insertarFilaArriba(): void {
    const tm = this.editorInstance?.getModule('table') as { insertRowAbove?: () => void } | null;
    tm?.insertRowAbove?.();
  }

  insertarFilaAbajo(): void {
    const tm = this.editorInstance?.getModule('table') as { insertRowBelow?: () => void } | null;
    tm?.insertRowBelow?.();
  }

  insertarColumnaIzquierda(): void {
    const tm = this.editorInstance?.getModule('table') as { insertColumnLeft?: () => void } | null;
    tm?.insertColumnLeft?.();
  }

  insertarColumnaDerecha(): void {
    const tm = this.editorInstance?.getModule('table') as { insertColumnRight?: () => void } | null;
    tm?.insertColumnRight?.();
  }

  eliminarFila(): void {
    const tm = this.editorInstance?.getModule('table') as { deleteRow?: () => void } | null;
    tm?.deleteRow?.();
  }

  eliminarColumna(): void {
    const tm = this.editorInstance?.getModule('table') as { deleteColumn?: () => void } | null;
    tm?.deleteColumn?.();
  }

  eliminarTabla(): void {
    const tm = this.editorInstance?.getModule('table') as { deleteTable?: () => void } | null;
    tm?.deleteTable?.();
  }

  previsualizarPdf(): void {
    const html = this.contenidoHtml();
    if (!html || !html.trim()) {
      this.toastService.error('Escriba contenido antes de previsualizar el PDF.');
      return;
    }

    this.previsualizando.set(true);
    this.machoteService
      .previewOficio(this.folio(), this.machote().id, {
        contenido_html: html,
        numero_oficio: this.numeroOficioInput() || null,
        asunto: this.asuntoInput() || null,
        promovente: this.promoventeInput() || null,
        dependencia: this.dependenciaInput() || null,
        seccion: this.seccionInput() || null,
        departamento: this.departamentoInput() || null,
        firmante_cargo: this.firmanteCargoInput() || null,
        firmante_nombre: this.firmanteNombreInput() || null,
      })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (blob) => {
          this.previsualizando.set(false);
          const url = URL.createObjectURL(blob);
          this.previewModalDocId.set(null);
          this.previewModalUrl.set(url);
        },
        error: async (err) => {
          this.previsualizando.set(false);
          let mensaje: string;
          if (err?.error instanceof Blob) {
            try {
              const text = await err.error.text();
              const parsed = JSON.parse(text);
              mensaje = parsed.message || parsed.error || text;
            } catch {
              mensaje = err.message || 'Error al procesar el documento';
            }
          } else {
            mensaje = extractErrorMessage(err);
          }
          this.toastService.error('Error al previsualizar PDF: ' + mensaje);
        },
      });
  }

  guardarOficio(): void {
    const html = this.contenidoHtml();
    if (!html || !html.trim()) {
      this.toastService.error('El contenido del oficio no puede estar vacío.');
      return;
    }

    this.guardando.set(true);
    this.machoteService
      .guardarOficio(this.folio(), this.machote().id, {
        contenido_html: html,
        numero_oficio: this.numeroOficioInput() || null,
        asunto: this.asuntoInput() || null,
        promovente: this.promoventeInput() || null,
        dependencia: this.dependenciaInput() || null,
        seccion: this.seccionInput() || null,
        departamento: this.departamentoInput() || null,
        firmante_cargo: this.firmanteCargoInput() || null,
        firmante_nombre: this.firmanteNombreInput() || null,
      })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (actualizado) => {
          this.guardando.set(false);
          this.expandido.set(false);
          this.toastService.success('Segundo documento (oficio resolutivo) guardado exitosamente.');
          this.oficioGuardado.emit(actualizado);
        },
        error: (err) => {
          this.guardando.set(false);
          this.toastService.error('Error al guardar oficio: ' + extractErrorMessage(err));
        },
      });
  }

  verPdfGuardado(): void {
    const docId = this.machote().oficioDocumentoId;
    if (docId) {
      this.previewModalUrl.set(null);
      this.previewModalDocId.set(docId);
      this.verPdf.emit({ documentoId: docId });
    }
  }

  descargarPdfGuardado(): void {
    const docId = this.machote().oficioDocumentoId;
    if (!docId) return;

    this.documentoService
      .downloadDocumento(docId)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (bytes) => {
          const blob = new Blob([new Uint8Array(bytes)], { type: 'application/pdf' });
          descargarBlob(blob, `oficio_${this.folio()}_v${this.machote().version}.pdf`);
        },
        error: (err) => this.toastService.error('Error al descargar: ' + extractErrorMessage(err)),
      });
  }

  cerrarModalPreview(): void {
    const url = this.previewModalUrl();
    if (url) {
      URL.revokeObjectURL(url);
    }
    this.previewModalUrl.set(null);
    this.previewModalDocId.set(null);
  }
}
