import { Component, computed, inject, input, resource } from '@angular/core';
import { DatePipe } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ResolucionService } from '../../services/resolucion.service';
import { SolicitudSnapshot } from '../../models/resolucion.model';
import { statusToClass } from '../../models/solicitud-status.util';

@Component({
  selector: 'app-historial-timeline',
  templateUrl: './historial-timeline.component.html',
  styleUrls: ['./historial-timeline.component.scss'],
  host: { class: 'd-block' },
  imports: [DatePipe],
})
export class HistorialTimelineComponent {
  private readonly resolucionService = inject(ResolucionService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  folio = input.required<string>();

  readonly historialResource = resource({
    params: () => ({ folio: this.folio() }),
    loader: async ({ params }) => {
      return await firstValueFrom(this.resolucionService.getHistorial(params.folio));
    },
  });

  readonly historial = computed<SolicitudSnapshot[]>(() => this.historialResource.value() ?? []);

  statusToClass = statusToClass;

  badgeLabel(snapshot: SolicitudSnapshot): string {
    return snapshot.resolucion?.sentido ?? snapshot.data.status ?? '';
  }

  badgeClass(snapshot: SolicitudSnapshot): string {
    return statusToClass(snapshot.resolucion?.sentido ?? snapshot.data.status ?? '');
  }

  snapshotLabel(snapshot: SolicitudSnapshot): string {
    const data = snapshot.data;
    return data.nombre_proyecto
      ?? data.denominacion_razon_social
      ?? data.solicitante
      ?? '';
  }

  descargar(snapshot: SolicitudSnapshot): void {
    const resolucionId = snapshot.resolucion?.id;
    if (!resolucionId) return;
    this.resolucionService.descargarResolucion(this.folio(), resolucionId).subscribe({
      next: (blob) => this.descargarBlob(blob, `resolucion_${this.folio()}_${resolucionId}.pdf`),
    });
  }

  verDetalle(snapshot: SolicitudSnapshot): void {
    this.router.navigate(['ver-historico', snapshot.id], {
      relativeTo: this.route.parent ?? this.route,
      state: { snapshot },
    });
  }

  private descargarBlob(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  }
}
